=Please analyze the following latest news article for NVIDIA and correlate it with our internal sales data from Google Sheets:

Title: {{ $json.articles[0].title }}
Source: {{ $json.articles[1].source.name }}
Published At: {{ $json.articles[0].publishedAt }}
Content/Description: {{ $json.articles[0].description ||$json.articles[0].content }}
URL: {{ $json.articles[0].url }}

Determine if there is any potential threat or opportunity, query the Google Sheet if needed, calculate the Risk Score, and generate the executive response.

parameters.jsCode:
// 1. استخراج الناتج المباشر من الـ AI Agent
let rawOutput = $input.first().json.output || "";

// 2. تنظيف وإزالة أغطية الكود الزائدة إن وجدت
let cleanedText = rawOutput
  .replace(/```html/gi, '')
  .replace(/```markdown/gi, '')
  .replace(/```/g, '')
  .trim();

// 3. تحويل تنسيقات الـ Markdown إلى عناصر HTML تفاعلية ومصممة
let formattedContent = cleanedText
  // تحويل العناوين إلى لون أخضر نيفيديا فاتح وواضح على الخلفية السوداء
  .replace(/###\s?\*\*(.*?)\*\*/g, '<h3 style="color: #76b900; margin-top: 20px; margin-bottom: 8px; font-size: 16px; border-bottom: 1px solid #333333; padding-bottom: 4px;">$1</h3>')
  .replace(/###\s?(.*)/g, '<h3 style="color: #76b900; margin-top: 20px; margin-bottom: 8px; font-size: 16px; border-bottom: 1px solid #333333; padding-bottom: 4px;">$1</h3>')

  // تحويل النص العريض إلى أبيض ناصع
  .replace(/\*\*(.*?)\*\*/g, '<strong style="color: #ffffff !important;">$1</strong>')

  // تحويل القوائم إلى أبيض مريح للعين
  .replace(/^\*\s?(.*)/gm, '<li style="margin-bottom: 6px; color: #e0e0e0 !important;">$1</li>')

  // الخط الفاصل
  .replace(/---/g, '<hr style="border: 0; border-top: 1px solid #333333; margin: 18px 0;">')

  // السطور الجديدة
  .replace(/\n/g, '<br>');

// 4. بناء هيكل البريد الإلكتروني (Full Dark Theme)
let htmlTemplate = `
<div style="background-color: #000000; padding: 20px; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;">
  <div style="max-width: 650px; margin: auto; background-color: #121212 !important; color: #ffffff !important; border-radius: 10px; overflow: hidden; border: 1px solid #222222;">

    <!-- Header -->
    <div style="background-color: #76b900; color: #000000; padding: 18px 20px; text-align: center;">
      <h2 style="margin: 0; font-size: 20px; font-weight: bold; letter-spacing: 0.5px; color: #000000 !important;">🟢 NVIDIA Aegis Pulse | Risk Alert</h2>
    </div>

    <!-- Content Body (Black Background) -->
    <div style="padding: 25px; line-height: 1.7; font-size: 14px; background-color: #121212 !important; color: #ffffff !important;">
      ${formattedContent}
    </div>

    <!-- Footer -->
    <div style="background-color: #080808 !important; border-top: 1px solid #222222; padding: 14px; text-align: center; font-size: 12px; color: #888888 !important;">
      🤖 Powered by <strong>NVIDIA Aegis Pulse Autonomous Engine</strong>
    </div>

  </div>
</div>
`;

// 5. إرجاع النتيجة لتغذية عقدة Gmail
return [{
  json: {
    htmlEmail: htmlTemplate,
    subject: "[NVIDIA Aegis Pulse] Market Risk & Intelligence Report"
  }
}];
